import{_ as n,o as r,c as e,ag as s,j as o}from"./chunks/framework.KxDd3USm.js";const A=JSON.parse('{"title":"03.3 模块化设计：内聚、耦合与模块原则 ★★★","description":"","frontmatter":{},"headers":[],"relativePath":"03-软件工程基础/03-模块化设计.md","filePath":"03-软件工程基础/03-模块化设计.md"}'),a={name:"03-软件工程基础/03-模块化设计.md"},l={class:"fig"},x={"data-figure-id":"figure-19",viewBox:"0 0 720 260",width:"100%",style:{"max-width":"720px"},role:"img","aria-label":"软件结构图载体：主模块 M 下设 A、B、C 三个二级模块，A 再管 D、E，D 和 E 共同调用 F。图上标注四个量：深度 4 层、宽度 3（二级最多三个并列）、M 的扇出 3、F 的扇入 2"},g={class:"fig"},d={"data-figure-id":"figure-20",viewBox:"0 0 720 272",width:"100%",style:{"max-width":"720px"},role:"img","aria-label":"内聚七级阶梯图：从 1 偶然、2 逻辑、3 时间、4 过程、5 通信、6 顺序到 7 功能，台阶逐级升高，颜色从灰到金再到绿，表示内聚强度递增、模块职责越来越单一"},i={class:"fig"},c={"data-figure-id":"figure-21",viewBox:"0 0 720 334",width:"100%",style:{"max-width":"720px"},role:"img","aria-label":"耦合七级关系图：每行都是模块 A 与模块 B，从上到下依次演示内容耦合（A 直接读写 B 内部）、公共耦合（共用全局学籍表）、外部耦合（共用全局变量）、控制耦合（传开关标志）、标记耦合（传整条记录）、数据耦合（只传学号）、非直接耦合（互不相识由主模块牵线），连线颜色红为高危、金为中等、绿为健康"};function h(u,t,q,p,y,_){return r(),e("div",null,[t[6]||(t[6]=s('<h1 id="_03-3-模块化设计-内聚、耦合与模块原则-★★★" tabindex="-1">03.3 模块化设计：内聚、耦合与模块原则 ★★★ <a class="header-anchor" href="#_03-3-模块化设计-内聚、耦合与模块原则-★★★" aria-label="Permalink to &quot;03.3 模块化设计：内聚、耦合与模块原则 ★★★&quot;">​</a></h1><h3 id="_3-0-为什么要-高内聚、低耦合" tabindex="-1">3.0 为什么要&quot;高内聚、低耦合&quot; <a class="header-anchor" href="#_3-0-为什么要-高内聚、低耦合" aria-label="Permalink to &quot;3.0 为什么要&quot;高内聚、低耦合&quot;&quot;">​</a></h3><p>软件要拆成模块，拆法有好坏：一个模块内部干的事<strong>越相关</strong>（内聚越高），越容易看懂、改起来越不容易牵连别处；模块之间<strong>越独立</strong>（耦合越低），一个模块改动对别的影响越小。&quot;高内聚、低耦合&quot;就是这两条经验的一句话版。<strong>内聚看模块内部，耦合看模块之间</strong>——先分清这个方向再背排序。</p><h3 id="_3-1-模块设计的六条原则-真题的-下列错误的是-常客" tabindex="-1">3.1 模块设计的六条原则（真题的&quot;下列错误的是&quot;常客） <a class="header-anchor" href="#_3-1-模块设计的六条原则-真题的-下列错误的是-常客" aria-label="Permalink to &quot;3.1 模块设计的六条原则（真题的&quot;下列错误的是&quot;常客）&quot;">​</a></h3><p>内聚与耦合只回答了&quot;模块怎么拆才算好&quot;里的一个维度。完整的模块设计原则是<strong>六条</strong>，其中三条专考：</p><p><strong>① 保持模块的大小适中</strong></p><ul><li>过大：内部可能揉进不同类型的功能，需要进一步划分，尽量让各模块功能单一；</li><li>过小：系统复杂度反而增加，<strong>模块之间的调用过于频繁，降低了模块的独立性</strong>。</li><li><strong>结论：模块规模不是越小越好</strong>——&quot;模块规模越小越好&quot;是真题的固定错项。</li></ul><p><strong>② 深度、宽度适中</strong></p><ul><li><strong>深度</strong> = 软件结构中模块的<strong>层数</strong>。层数过多 → 说明有些模块设计得过于简单，应考虑<strong>合并</strong>。</li><li><strong>宽度</strong> = 软件结构中<strong>同一层次上模块总数的最大值</strong>。影响宽度最大的因素是<strong>模块的扇出</strong>。宽度越大系统越复杂。</li></ul><p><strong>③ 扇入、扇出系数要合理</strong></p><ul><li><strong>扇入</strong> = 该模块的<strong>直接上级模块的个数</strong>（有多少个模块调用它）；</li><li><strong>扇出</strong> = 该模块的<strong>直属下级模块的个数</strong>（它调用了多少个模块）；</li><li>原则是&quot;<strong>多扇入、少扇出</strong>&quot;：扇入大 = 复用性好（很多模块都用它，改好一处全都受益）；扇出小 = 该模块自身比较独立、不牵动一大片。经典的错项写法是反过来写&quot;多扇出、少扇入&quot;。</li></ul><p>四个量都在同一张软件结构图上数，见下图（数法随图注）：</p>',12)),o("figure",l,[(r(),e("svg",x,[...t[0]||(t[0]=[s('<line class="e" x1="250" y1="44" x2="115" y2="78"></line><line class="e" x1="250" y1="44" x2="250" y2="78"></line><line class="e" x1="250" y1="44" x2="385" y2="78"></line><line class="e" x1="115" y1="100" x2="70" y2="130"></line><line class="e" x1="115" y1="100" x2="196" y2="130"></line><line class="e" x1="70" y1="152" x2="136" y2="186"></line><line class="e" x1="196" y1="152" x2="160" y2="186"></line><rect class="mb" x="218" y="22" width="64" height="22"></rect><text class="bt" x="250" y="37">M 主控</text><rect class="mb" x="83" y="78" width="64" height="22"></rect><text class="bt" x="115" y="93">A</text><rect class="mb" x="218" y="78" width="64" height="22"></rect><text class="bt" x="250" y="93">B</text><rect class="mb" x="353" y="78" width="64" height="22"></rect><text class="bt" x="385" y="93">C</text><rect class="mb" x="38" y="130" width="64" height="22"></rect><text class="bt" x="70" y="145">D</text><rect class="mb" x="164" y="130" width="64" height="22"></rect><text class="bt" x="196" y="145">E</text><rect class="hot" x="128" y="186" width="64" height="22"></rect><text class="bt" x="160" y="201">F 复用</text><text class="ann2" x="438" y="37">深度 = 4 层（M、二级、三级、F）</text><text class="ann2" x="438" y="93">宽度 = 3（并列最多的一层是 A B C）</text><text class="ann" x="288" y="60">M 扇出 = 3</text><text class="ann" x="136" y="118">A 扇出 = 2</text><text class="ann" x="206" y="204">F 扇入 = 2（D、E 都调用它）</text><text class="ann2" x="28" y="240">数法：深度自上而下数层；宽度找并列最多的一层；扇入数&quot;谁把线指进来&quot;，扇出数&quot;它把线指出去几个&quot;。</text>',27)])])),t[1]||(t[1]=o("figcaption",null,'绿色 F 是"多扇入"的模范（一处实现、多处复用）；若把 D、E 合并成一个大模块，深度变浅但内聚可能变差——四个量要一起权衡，这正是"适中"二字的含义。',-1))]),t[7]||(t[7]=s(`<p><strong>④ 模块的作用域应该在控制域之内</strong>（最绕、最爱考）</p><ul><li><strong>控制域</strong> = 这个模块<strong>本身</strong>以及所有<strong>直接或间接从属于它</strong>的模块的集合；</li><li><strong>作用域</strong> = 受该模块<strong>内一个判定所影响</strong>的所有模块的集合；</li><li>要求：<strong>判定的影响范围必须落在该模块能控制的范围内</strong>。</li></ul><p><strong>违反时的样子与改法</strong>（一眼看懂）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>        M（主控）</span></span>
<span class="line"><span>       /  \\</span></span>
<span class="line"><span>      A    B        判定 P 写在 A 里面，</span></span>
<span class="line"><span>     (P)             但 P 的结果要影响兄弟模块 B</span></span>
<span class="line"><span></span></span>
<span class="line"><span>A 的控制域 = {A}   ← A 没有下级，管不到 B</span></span>
<span class="line"><span>A 的作用域 = {B}   ← P 影响的是 B</span></span>
<span class="line"><span>{B} ⊄ {A}  → 违反！A 只能在算完之后把结果当参数往外传，耦合被迫升高</span></span></code></pre></div><p>改法二选一：<strong>把判定 P 上移到 M</strong>（此时 M 的控制域 = {M, A, B} ⊇ {B} ✓）；或者<strong>把被影响的模块 B 下移到 A 之下</strong>。</p><p><strong>⑤ 功能应该是可预测的</strong> 模块的功能要单一、结果要可预期。反例：一个模块的输出取决于某个全局变量的当前值，同样的入参可能返回不同结果，调用者无法预知——这就是&quot;功能不可预测&quot;，属设计缺陷。<strong>&quot;模块的功能应该是不可预测的&quot;是真题的固定错项。</strong></p><p><strong>⑥ 高内聚、低耦合</strong>：见 3.2、3.3。</p><h3 id="_3-2-内聚七级-从低到高-必须背顺序" tabindex="-1">3.2 内聚七级（从低到高，必须背顺序） <a class="header-anchor" href="#_3-2-内聚七级-从低到高-必须背顺序" aria-label="Permalink to &quot;3.2 内聚七级（从低到高，必须背顺序）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>级别</th><th>名称</th><th>含义</th><th>一句话识别</th></tr></thead><tbody><tr><td>1</td><td><strong>偶然内聚</strong>（巧合内聚）</td><td>动作之间毫无关系，凑在一起（如&quot;为了省事把几个无关函数塞一个模块&quot;）</td><td>&quot;没什么关系，硬凑&quot;</td></tr><tr><td>2</td><td><strong>逻辑内聚</strong></td><td>逻辑上<strong>相似</strong>但功能用途无关（如一个模块按参数分别执行打印输入/打印输出）</td><td>&quot;相似但无关&quot;</td></tr><tr><td>3</td><td><strong>时间内聚</strong>（瞬时内聚）</td><td>动作无关，但必须在<strong>同一时间</strong>（同一时间间隔内）执行（如初始化模块）</td><td>&quot;同一时间&quot;</td></tr><tr><td>4</td><td><strong>过程内聚</strong></td><td>动作关系不大，但必须<strong>按特定次序</strong>执行</td><td>&quot;按次序但无实质关系&quot;</td></tr><tr><td>5</td><td><strong>通信内聚</strong></td><td>各动作对<strong>同一数据</strong>进行操作（如对同一份数据先读后存再打印）</td><td>&quot;围绕同一数据&quot;</td></tr><tr><td>6</td><td><strong>顺序内聚</strong></td><td>前一个动作的<strong>输出</strong>正好是后一个动作的<strong>输入</strong>（必须顺序执行）</td><td>&quot;接力棒&quot;</td></tr><tr><td>7</td><td><strong>功能内聚</strong></td><td>所有部分合起来完成<strong>单一功能</strong>（如计算利息），协同工作缺一不可</td><td>&quot;就是一个功能&quot;</td></tr></tbody></table><p>这七级是一条<strong>阶梯</strong>：每一级都比下一级&quot;更团结&quot;，升级的方向就是模块内部的事越归拢到一件事上。</p>`,10)),o("figure",g,[(r(),e("svg",d,[...t[2]||(t[2]=[s('<text class="tt" x="20" y="26">内聚强度阶梯（低 → 高，考试要能默写顺序）</text><rect class="s1" x="20" y="212" width="94" height="24"></rect><rect class="s1" x="118" y="190" width="94" height="46"></rect><rect class="s1" x="216" y="168" width="94" height="68"></rect><rect class="s2" x="314" y="146" width="94" height="90"></rect><rect class="s2" x="412" y="124" width="94" height="112"></rect><rect class="s3" x="510" y="102" width="94" height="134"></rect><rect class="s3" x="608" y="80" width="94" height="156"></rect><text class="st" x="67" y="228">1 偶然</text><text class="st" x="165" y="206">2 逻辑</text><text class="st" x="263" y="184">3 时间</text><text class="st" x="361" y="162">4 过程</text><text class="st" x="459" y="140">5 通信</text><text class="st" x="557" y="118">6 顺序</text><text class="st" x="655" y="96">7 功能</text><text class="mt" x="360" y="260">每往上一级，&quot;凑数&quot;的成分就少一分：从硬凑 → 相似 → 同时 → 同序 → 同数据 → 接力 → 一事</text>',16)])])),t[3]||(t[3]=o("figcaption",null,'灰色三级靠"外部理由"（相似/同时/同序）抱团，金色两级靠数据与次序，绿色顶级只靠功能本身——判级先问"它们为什么在一个模块里"。',-1))]),t[8]||(t[8]=s('<p><strong>学生学籍场景走一遍</strong>（同一个领域，七种拆法对号入座）：</p><ol><li><strong>偶然</strong>——&quot;杂项模块&quot;：打印学号、续借图书、充饭卡塞在一起，&quot;哪段代码没人管就扔进来&quot;；</li><li><strong>逻辑</strong>——&quot;打印模块&quot;：靠传模式切换打印成绩单/借阅单/欠费单，都是&quot;打印&quot;但干的互不相关；</li><li><strong>时间</strong>——&quot;启动模块&quot;：开数据库、读字典、清屏、复位计时器，互不相干但都得在启动这一刻做；</li><li><strong>过程</strong>——&quot;成绩流程模块&quot;：先统计人数、再打印名单、后画柱状图，顺序不能乱，但<strong>步与步之间不传数据</strong>；</li><li><strong>通信</strong>——&quot;学籍表模块&quot;：查询、改地址、注销三个操作<strong>都围着同一张学籍表</strong>，各做各的；</li><li><strong>顺序</strong>——&quot;成绩统计模块&quot;：读答卷 → 算分数 → 画分布图，<strong>上一步的输出就是下一步的输入</strong>，接力棒；</li><li><strong>功能</strong>——&quot;应纳税额计算模块&quot;：每一行代码都缺一不可，拆开就不再是&quot;算税&quot;。</li></ol><p><strong>默写口诀（低→高）：偶然笑、逻辑杂、时间同分钟、过程有先后、通信同数据、顺序接力跑、功能只一招。</strong></p><h3 id="_3-3-耦合七级-从高到低-必须背顺序" tabindex="-1">3.3 耦合七级（从高到低，必须背顺序） <a class="header-anchor" href="#_3-3-耦合七级-从高到低-必须背顺序" aria-label="Permalink to &quot;3.3 耦合七级（从高到低，必须背顺序）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>级别</th><th>名称</th><th>含义</th><th>一句话识别</th></tr></thead><tbody><tr><td>1</td><td><strong>内容耦合</strong></td><td>一个模块直接访问另一个模块的<strong>内部</strong>数据或代码；或不经正常入口转入内部；或两块代码重叠；或一个模块有多个入口</td><td>&quot;掀开别人内脏&quot;</td></tr><tr><td>2</td><td><strong>公共耦合</strong></td><td>多个模块通过<strong>同一公共数据环境</strong>（全局数据结构，如一个大数组、一个公共文件）传递信息</td><td>&quot;共用一个大仓库&quot;</td></tr><tr><td>3</td><td><strong>外部耦合</strong></td><td>多个模块访问<strong>同一全局简单变量</strong>（不是数据结构），且不是通过参数表传递</td><td>&quot;共用一个全局变量&quot;</td></tr><tr><td>4</td><td><strong>控制耦合</strong></td><td>传递的信息中含<strong>控制信号</strong>（如开关标志决定对方走哪个分支）</td><td>&quot;传的是命令不是数据&quot;</td></tr><tr><td>5</td><td><strong>标记耦合</strong></td><td>通过参数表传递<strong>记录信息/数据结构</strong>（而非简单变量）</td><td>&quot;传一整条记录&quot;</td></tr><tr><td>6</td><td><strong>数据耦合</strong></td><td>通过参数表传递<strong>简单数据</strong></td><td>&quot;传一个数&quot;</td></tr><tr><td>7</td><td><strong>非直接耦合</strong></td><td>两模块之间<strong>没有直接关系</strong>，联系完全通过<strong>主模块的控制和调用</strong>实现</td><td>&quot;各干各的，上级牵线&quot;</td></tr></tbody></table><p>七种耦合放在**同一对模块 A（录入）、B（报表）**身上画出来——换的是联系方式，不换角色：</p>',6)),o("figure",i,[(r(),e("svg",c,[...t[4]||(t[4]=[s('<defs><marker id="cp-a" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0L8 4L0 8z" fill="var(--line-strong)"></path></marker></defs><text class="tt" x="20" y="26">同一对 A、B 的七种联系方式（红→金→绿：坏→一般→好）</text><text class="nm" x="16" y="60">1 内容</text><rect class="bx" x="196" y="46" width="64" height="22"></rect><text class="bt" x="228" y="61">A</text><rect class="bx" x="424" y="46" width="64" height="22"></rect><text class="bt" x="456" y="61">B</text><path class="rd" d="M260 57 H418" marker-end="url(#cp-a)"></path><text class="tx" x="506" y="61">A 直接读写 B 的内部数据</text><text class="nm" x="16" y="98">2 公共</text><rect class="bx" x="196" y="84" width="64" height="22"></rect><text class="bt" x="228" y="99">A</text><rect class="bx" x="424" y="84" width="64" height="22"></rect><text class="bt" x="456" y="99">B</text><rect class="gb" x="284" y="85" width="120" height="20" rx="4"></rect><text class="gs" x="344" y="99">全局学籍表</text><path class="rd" d="M260 95 H284"></path><path class="rd" d="M404 95 H424"></path><text class="tx" x="506" y="99">共用一整个公共仓库（结构/文件）</text><text class="nm" x="16" y="136">3 外部</text><rect class="bx" x="196" y="122" width="64" height="22"></rect><text class="bt" x="228" y="137">A</text><rect class="bx" x="424" y="122" width="64" height="22"></rect><text class="bt" x="456" y="137">B</text><rect class="gb" x="300" y="123" width="88" height="20" rx="4"></rect><text class="gs" x="344" y="137">全局变量 cnt</text><path class="rd" d="M260 133 H300"></path><path class="rd" d="M388 133 H424"></path><text class="tx" x="506" y="137">只共用一个全局简单变量</text><text class="nm" x="16" y="174">4 控制</text><rect class="bx" x="196" y="160" width="64" height="22"></rect><text class="bt" x="228" y="175">A</text><rect class="bx" x="424" y="160" width="64" height="22"></rect><text class="bt" x="456" y="175">B</text><path class="gd" d="M260 171 H418" marker-end="url(#cp-a)"></path><text class="gs" x="344" y="166">flag：打不打印？</text><text class="tx" x="506" y="175">传开关，B 的分支由 A 定</text><text class="nm" x="16" y="212">5 标记</text><rect class="bx" x="196" y="198" width="64" height="22"></rect><text class="bt" x="228" y="213">A</text><rect class="bx" x="424" y="198" width="64" height="22"></rect><text class="bt" x="456" y="213">B</text><path class="gd" d="M260 209 H418" marker-end="url(#cp-a)"></path><text class="gs" x="344" y="204">整条学生记录</text><text class="tx" x="506" y="213">传结构，用几个字段也照传</text><text class="nm" x="16" y="250">6 数据</text><rect class="bx" x="196" y="236" width="64" height="22"></rect><text class="bt" x="228" y="251">A</text><rect class="bx" x="424" y="236" width="64" height="22"></rect><text class="bt" x="456" y="251">B</text><path class="ok" d="M260 247 H418" marker-end="url(#cp-a)"></path><text class="gs" x="344" y="242">学号（简单变量）</text><text class="tx" x="506" y="251">只传需要的那个数</text><text class="nm" x="16" y="288">7 非直接</text><rect class="bx" x="196" y="274" width="64" height="22"></rect><text class="bt" x="228" y="289">A</text><rect class="bx" x="424" y="274" width="64" height="22"></rect><text class="bt" x="456" y="289">B</text><rect class="gb" x="312" y="266" width="64" height="18" rx="4"></rect><text class="gs" x="344" y="279">主模块</text><path class="ok" d="M328 284 L260 289"></path><path class="ok" d="M360 284 L424 289"></path><text class="tx" x="506" y="289">互不相识，上级各叫各的</text><text class="mt" x="360" y="324" text-anchor="middle">红三行：沾内部或沾全局，改一处牵一片；金两行：传&quot;命令&quot;或传&quot;整条记录&quot;；绿两行才是设计目标。</text>',64)])])),t[5]||(t[5]=o("figcaption",null,'第 2、3 行只差一个"数据结构 vs 简单变量"，第 4、5 行只差"传的是命令还是内容"——3.4 的四组辨析全部能在这张图上指出来。',-1))]),t[9]||(t[9]=s('<p><strong>默写口诀（强→弱）：内容最坏公共外，控制标记中间摆，数据、非直接最干净。</strong></p><h3 id="_3-4-反例演示-最易混四组" tabindex="-1">3.4 反例演示（最易混四组） <a class="header-anchor" href="#_3-4-反例演示-最易混四组" aria-label="Permalink to &quot;3.4 反例演示（最易混四组）&quot;">​</a></h3><ol><li><strong>逻辑内聚 vs 偶然内聚</strong>：动作之间&quot;有点相似&quot;（都跟打印/输入输出沾边）→ 逻辑内聚；&quot;完全没关系&quot;→ 偶然内聚。判别标准是<strong>相似性</strong>是否存在。</li><li><strong>时间内聚 vs 过程内聚</strong>：都是&quot;关系不大硬放一起&quot;，区别在<strong>约束是&quot;同时&quot;还是&quot;先后&quot;</strong>——初始化必须一起做 = 时间；必须按某次序执行 = 过程。</li><li><strong>公共耦合 vs 外部耦合</strong>：共用的是<strong>数据结构</strong>（一整个数组/记录/文件）→ 公共耦合；只是<strong>简单变量</strong>（一个全局计数器）→ 外部耦合。</li><li><strong>标记耦合 vs 数据耦合</strong>：参数传的是<strong>一条记录/结构</strong>（整个学生信息）→ 标记耦合；只是<strong>一个简单变量</strong>（学号这一个数）→ 数据耦合。</li></ol><p><strong>再强调一处易错</strong>：耦合的<strong>数据类</strong>三项（控制 &gt; 标记 &gt; 数据）排序时，<strong>&quot;传记录&quot;比&quot;传简单变量&quot;耦合高</strong>——因为在传递的内容里，前者包含了后者的全部信息，改记录结构会牵连更多模块。</p><p><strong>应试动作</strong>：① 两个排序必须能默写——内聚从&quot;凑（偶然）&quot;到&quot;专（功能）&quot;，耦合从&quot;掀内脏（内容）&quot;到&quot;不认识（非直接）&quot;；② 做题先抓题干关键词（同一时间/同一数据/接力/命令/记录/变量/全局）对号入座；③ 模块原则题抓三个&quot;反向错项&quot;——&quot;越小越好&quot;&quot;多扇出少扇入&quot;&quot;功能不可预测&quot;，见到就选它错。</p>',5))])}const m=n(a,[["render",h]]);export{A as __pageData,m as default};
